// Get user data - handle both array response and error response
const userData = $('Get User Data').all()[0]?.json;
let userArr = [];
let userError = null;

if (Array.isArray(userData)) {
  userArr = userData;
} else if (userData && userData.code) {
  userError = userData.message || 'Supabase query error';
} else {
  // Handle other formats
  userArr = [];
}

const total = userArr.length;
const now = new Date();
const weekAgo = new Date(now - 7*24*60*60*1000);
const monthAgo = new Date(now - 30*24*60*60*1000);
const newThisWeek = userArr.filter(u => u.created_at && new Date(u.created_at) > weekAgo).length;
const newThisMonth = userArr.filter(u => u.created_at && new Date(u.created_at) > monthAgo).length;

// GitHub issues
let ghIssues = [];
let ghError = null;
try {
  const ghData = $('Get GitHub Issues').all()[0]?.json;
  if (Array.isArray(ghData)) {
    ghIssues = ghData.slice(0, 5);
  } else if (ghData && ghData.message) {
    ghError = ghData.message;
  }
} catch(e) {
  ghError = 'GitHub query failed';
}

// Stripe revenue
let stripeRevenue = null;
let stripeError = null;
try {
  const stripeData = $('Get Stripe Revenue').all()[0]?.json;
  if (stripeData && stripeData.data) {
    const charges = stripeData.data;
    const mtd = charges
      .filter(c => c.status === 'succeeded' && new Date(c.created * 1000) > monthAgo)
      .reduce((sum, c) => sum + c.amount, 0) / 100;
    stripeRevenue = mtd;
  } else if (stripeData && stripeData.error) {
    stripeError = stripeData.error.message;
  }
} catch(e) {
  stripeError = 'Stripe query failed';
}

// Build message (plain text, no Markdown to avoid JSON issues)
let msg = `⭕ Fractionl Circle: Weekly digest\n`;
msg += `Date: ${now.toISOString().split('T')[0]}\n\n`;

if (userError) {
  msg += `Users: ERROR - ${userError}\n`;
} else {
  msg += `Users: ${total} total | ${newThisWeek} new this week | ${newThisMonth} new this month\n`;
}

if (stripeRevenue !== null) {
  msg += `Revenue MTD: $$${stripeRevenue.toFixed(2)}\n`;
} else if (stripeError) {
  msg += `Revenue: ERROR - ${stripeError}\n`;
} else {
  msg += `Revenue: No Stripe key configured\n`;
}

if (ghIssues.length > 0) {
  msg += `\nOpen GitHub Issues (${ghIssues.length}): \n`;
  ghIssues.forEach(i => {
    msg += `- #${i.number}: ${i.title}\n`;
  });
} else if (ghError) {
  msg += `GitHub Issues: ERROR - ${ghError}\n`;
} else {
  msg += `GitHub Issues: None open (or no repo)\n`;
}

msg += `\nNext: Agatha to review + feed to Product Agent. No changes without approval.`;

// Build Telegram payload directly to avoid JSON template issues
const telegramPayload = {
  chat_id: "6773796504",
  text: msg,
  parse_mode: "Markdown"
};

// Structured output for Product Agent to consume
const structured = {
  app: "Fractionl Circle",
  date: now.toISOString().split('T')[0],
  users: { total, newThisWeek, newThisMonth },
  revenue_mtd: stripeRevenue,
  open_issues: ghIssues.map(i => ({ number: i.number, title: i.title, labels: (i.labels||[]).map(l=>l.name) })),
  errors: { user: userError, github: ghError, stripe: stripeError },
  agatha_review_required: true
};

return [{ json: { telegramPayload, structured } }];

// audit-fix 2026-05-19: pull Supabase service_role from bound credential
const __supa = await this.getCredentials('supabaseApi');
const __SUPABASE_KEY = (__supa && __supa.serviceRole) || '';
if (!__SUPABASE_KEY) throw new Error('Supabase service_role credential not bound');
// Injected fetch-based httpRequest shim (task-runner-safe)
const __helpers = this.helpers;
async function __httpRequest(opts) {
  const method = (opts.method || 'GET').toUpperCase();
  const url = opts.url;
  const headers = Object.assign({}, opts.headers || {});
  const cfg = {
    method,
    url,
    headers,
    json: opts.json !== false,
    returnFullResponse: true,
    timeout: opts.timeout || 30000,
  };
  if (opts.body !== undefined && opts.body !== null) {
    cfg.body = opts.body;
    if (typeof opts.body === 'object' && !headers['Content-Type'] && !headers['content-type']) {
      cfg.headers['Content-Type'] = 'application/json';
    }
  }
  let res;
  try {
    res = await __helpers.httpRequest(cfg);
  } catch (err) {
    const status = err.httpCode || err.statusCode || (err.response && err.response.status) || 0;
    const body = (err.response && err.response.body) || err.body || null;
    const wrapped = new Error('HTTP ' + (status || 'network') + ': ' + (err.message || String(err)).slice(0, 300));
    wrapped.httpCode = status;
    wrapped.body = body;
    throw wrapped;
  }
  const status = res.statusCode || res.status || 0;
  const body = res.body !== undefined ? res.body : res;
  if (status < 200 || status >= 300) {
    const e = new Error('HTTP ' + status + ': ' + String(body).slice(0, 300));
    e.httpCode = status;
    e.body = body;
    throw e;
  }
  return body;
}

let startTime = Date.now();
try {
  startTime = $('Webhook').first().json.headers['x-request-start'];
} catch(e) {
  // Ignore missing webhook node
}
const duration = Date.now() - (parseInt(startTime) || Date.now());

const payload = {
  workflow_id: $workflow.id,
  workflow_name: $workflow.name,
  agent_id: $input.first()?.json?.agent_id || 'system',
  duration_ms: duration,
  api_calls: $input.first()?.json?.api_call_count || 0,
  cost_usd: $input.first()?.json?.total_cost || 0,
  outcome: $input.first()?.json?.outcome || 'completed',
  outcome_count: $input.first()?.json?.result_count || 0,
  quality_score: $input.first()?.json?.quality_score || null,
  status: 'success',
  metadata: JSON.stringify({ source: 'n8n_auto_log' })
};

const response = await __httpRequest({
  method: 'POST',
  url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/workflow_runs',
  headers: {
    'apikey': __SUPABASE_KEY,
    'Authorization': `Bearer ${__SUPABASE_KEY}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: payload,
  json: true
});

return [{ json: { logged: true, ...payload } }];
